#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

PROJECT_ID="comfforts-369117"
REGION="us-west1"
REPOSITORY="hankgalt/ai_finance_assitant"
RUNTIME_SECRET_ID="aifa-staging-qdrant-runtime-api-key"
RELEASE_SECRET_ID="aifa-staging-qdrant-release-api-key"
BACKEND_SERVICE="aifa-staging-backend"
QDRANT_CONSOLE_URL="https://cloud.qdrant.io/"
SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd "$SCRIPT_DIR/../../.." && pwd)
CONTRACT="$REPO_ROOT/contracts/deployment/knowledge-release.v1.json"
PYTHON="$REPO_ROOT/backend/.venv/bin/python"

banner "Shared knowledge release"

# Verify the exact merged revision and local tools before any external write.
stage "Verify revision, identity, and tools"
for tool in git gh gcloud jq curl; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not available on PATH"; exit 1; }
done
[[ -x "$PYTHON" ]] || { warn "backend virtual environment is missing; run make backend-sync"; exit 1; }
cd "$REPO_ROOT"
[[ "$(git branch --show-current)" == "main" ]] || { warn "switch to main before releasing"; exit 1; }
[[ -z "$(git status --porcelain)" ]] || { warn "the worktree must be clean before releasing"; exit 1; }
git fetch origin main --quiet
[[ "$(git rev-parse HEAD)" == "$(git rev-parse origin/main)" ]] || {
  warn "local main must exactly match origin/main"
  exit 1
}
gh auth status >/dev/null
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)')
[[ "$ACTIVE_ACCOUNT" == "vtalwar.w@comfforts.com" ]] || {
  warn "active gcloud account must be vtalwar.w@comfforts.com"
  exit 1
}
[[ "$(gcloud config get-value project 2>/dev/null)" == "$PROJECT_ID" ]] || {
  warn "active gcloud project must be $PROJECT_ID"
  exit 1
}
say "Verified merged main, GitHub authentication, and $ACTIVE_ACCOUNT on $PROJECT_ID."

# The source is the already-qualified persistent local Qdrant volume.
stage "Verify the local qualified collections"
curl --silent --show-error --fail --max-time 10 \
  "http://127.0.0.1:6333/collections" >/dev/null || {
  warn "local Qdrant is unavailable; start Docker and run make qdrant-up"
  exit 1
}
for collection in $(jq -r '.collections[] | .current_collection, .rollback_collection' "$CONTRACT"); do
  curl --silent --show-error --fail --max-time 10 \
    "http://127.0.0.1:6333/collections/$collection" >/dev/null || {
    warn "required local collection is missing: $collection"
    exit 1
  }
done
say "All current and rollback collections exist in the local source."

# Use the exact runtime version already selected by the deployed backend.
stage "Verify runtime key and provider boundary"
RUNTIME_VERSION=$(gh variable get GCP_QDRANT_SECRET_VERSION \
  --repo "$REPOSITORY" --env staging)
[[ "$RUNTIME_VERSION" =~ ^[1-9][0-9]*$ ]] || {
  warn "staging GCP_QDRANT_SECRET_VERSION must be a positive numeric version"
  exit 1
}
RUNTIME_STATE=$(gcloud secrets versions describe "$RUNTIME_VERSION" \
  --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID" --format='value(state)')
[[ "$RUNTIME_STATE" == "ENABLED" ]] || {
  warn "runtime secret version $RUNTIME_VERSION is not enabled"
  exit 1
}
say "Selected enabled runtime secret version $RUNTIME_VERSION without reading its payload."
say "The release will prove that this key can read collections and receives HTTP 403 on write."
SERVICE_DESCRIPTION_FILE=$(mktemp "${TMPDIR:-/tmp}/aifa-backend-service.XXXXXX")
trap 'rm -f "$SERVICE_DESCRIPTION_FILE"' EXIT
gcloud run services describe "$BACKEND_SERVICE" \
  --project="$PROJECT_ID" --region="$REGION" --format=json > "$SERVICE_DESCRIPTION_FILE"
jq -e '
  (.spec.template.spec.containers[] | select(.name == "backend") | .env // []) as $env |
  any($env[]; .name == "AIFA_PROVIDER_MODE" and .value == "credential_free") and
  any($env[]; .name == "AIFA_MODEL_MODE" and .value == "credential_free") and
  all($env[];
    (.name | ascii_upcase) as $name |
    [
      "AIFA_ALPHA_VANTAGE_API_KEY",
      "AIFA_ALPHA_VANTAGE_TERMS_APPROVED",
      "AIFA_MASSIVE_API_KEY",
      "AIFA_MASSIVE_TERMS_APPROVED",
      "AIFA_OPENAI_API_KEY",
      "AIFA_OPENAI_TERMS_APPROVED",
      "AIFA_TAVILY_API_KEY",
      "AIFA_TAVILY_TERMS_APPROVED",
      "OPENAI_API_KEY"
    ] | index($name) == null
  )
' "$SERVICE_DESCRIPTION_FILE" >/dev/null || {
  warn "deployed backend provider/model modes or credential boundary are not approved"
  exit 1
}
say "Verified the deployed backend is credential-free and has no live-provider credential flags."

# The release key is entered only in Secret Manager and is never injected into Cloud Run.
stage "Create or select the temporary release key"
RELEASE_VERSION=$(gcloud secrets versions list "$RELEASE_SECRET_ID" \
  --project="$PROJECT_ID" --filter='state=enabled' --sort-by='~createTime' \
  --limit=1 --format='value(name)')
RELEASE_VERSION="${RELEASE_VERSION##*/}"
if [[ "$RELEASE_VERSION" =~ ^[1-9][0-9]*$ ]] && \
  confirm "Reuse enabled release-key secret version $RELEASE_VERSION?"; then
  say "Reusing enabled version $RELEASE_VERSION."
else
  open_url "$QDRANT_CONSOLE_URL"
  step "Open finance-assistant-demo → API Keys and create a cluster-wide manage/write key."
  step "Name it finance-assistant-staging-release-$(date -u +%Y%m%d) and set a 7-day expiration."
  open_url "https://console.cloud.google.com/security/secret-manager/secret/$RELEASE_SECRET_ID/versions?project=$PROJECT_ID"
  step "Choose New version, paste that release key, and enable the version."
  pause "Return here after the enabled version exists. Press Enter to continue."
  RELEASE_VERSION=$(gcloud secrets versions list "$RELEASE_SECRET_ID" \
    --project="$PROJECT_ID" --filter='state=enabled' --sort-by='~createTime' \
    --limit=1 --format='value(name)')
  RELEASE_VERSION="${RELEASE_VERSION##*/}"
fi
[[ "$RELEASE_VERSION" =~ ^[1-9][0-9]*$ ]] || {
  warn "no enabled numeric version exists for $RELEASE_SECRET_ID"
  exit 1
}
say "Selected release secret version $RELEASE_VERSION without reading its payload."

# Transfer only missing collections, evaluate current collections, and prove alias rollback.
stage "Transfer and qualify shared knowledge"
REVISION=$(git rev-parse HEAD)
EVIDENCE="$REPO_ROOT/backend/artifacts/knowledge/deployment/staging-release-$REVISION.json"
confirm "Transfer missing snapshots and run the reviewed qualification now?" || exit 1
"$PYTHON" -m ai_finance_assistant.knowledge.release \
  --repo-root "$REPO_ROOT" \
  --contract "$CONTRACT" \
  execute \
  --release-api-key-file <(gcloud secrets versions access "$RELEASE_VERSION" \
    --secret="$RELEASE_SECRET_ID" --project="$PROJECT_ID") \
  --runtime-api-key-file <(gcloud secrets versions access "$RUNTIME_VERSION" \
    --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID") \
  --backend-service-description "$SERVICE_DESCRIPTION_FILE" \
  --evidence-path "$EVIDENCE"
say "Collections passed exact manifest/count checks, fixed qrels, alias rollback, and runtime denial."

# Revoke the external key, prove rejection, and destroy its Secret Manager copy.
stage "Revoke and remove the temporary release key"
open_url "$QDRANT_CONSOLE_URL"
step "Open finance-assistant-demo → API Keys and revoke the temporary release key."
pause "Return here after Qdrant shows the key revoked. Press Enter to verify."
"$PYTHON" -m ai_finance_assistant.knowledge.release \
  --repo-root "$REPO_ROOT" \
  --contract "$CONTRACT" \
  finalize-revocation \
  --release-api-key-file <(gcloud secrets versions access "$RELEASE_VERSION" \
    --secret="$RELEASE_SECRET_ID" --project="$PROJECT_ID") \
  --evidence-path "$EVIDENCE"
confirm "Permanently destroy release secret version $RELEASE_VERSION in Secret Manager?" || exit 1
gcloud secrets versions destroy "$RELEASE_VERSION" \
  --secret="$RELEASE_SECRET_ID" --project="$PROJECT_ID" --quiet
"$PYTHON" -m ai_finance_assistant.knowledge.release \
  record-secret-destroyed --evidence-path "$EVIDENCE"
jq -e '
  .status == "qualified" and
  .runtime_permission.passed == true and
  .deployed_provider_boundary.passed == true and
  .release_key.qdrant_revoked == true and
  .release_key.secret_version_destroyed == true and
  .provider_boundary.provider_mode == "credential_free" and
  .provider_boundary.model_mode == "credential_free" and
  .secret_payloads_recorded == false
' "$EVIDENCE" >/dev/null
say "Release evidence is complete and contains no credential payload."
say "Provider and model modes remain credential-free."
note "$EVIDENCE"

finish
}

run_wizard "$@"; exit
